import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, Box3 } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Derive text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find(item => item.role === 'headline') || items[0];
  const labelText = textItem?.text ?? 'Features 2';
  const fontSize = textItem?.typography?.fontSize ?? 39;

  // --- Plane setup ---
  const atlasW = 512, atlasH = 320; // from source rect
  const aspect = atlasW / atlasH;
  const planeW = 2;
  const planeH = planeW / aspect; // ~1.25

  const geometry = new PlaneGeometry(planeW, planeH);
  const material = new MeshBasicNodeMaterial({
    color: '#ffffff',
    transparent: true,
  });

  const plane = new Mesh(geometry, material);
  group.add(plane);

  // --- Load texture (async) ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text overlay ---
  const textGroup = ctx.fontAtlas.createText(labelText, {
    fontSize: fontSize,
    color: '#e8ecf2', // paper
    align: 'center',
  });

  // Scale text to fit plane width (80% width, uniform)
  const box = new Box3().setFromObject(textGroup);
  const textWidth = box.max.x - box.min.x;
  const targetWidth = planeW * 0.8;
  if (textWidth > 0) {
    const scale = targetWidth / textWidth;
    textGroup.scale.set(scale, scale, 1);
  }

  // Center text on plane, slightly forward to avoid z-fighting
  textGroup.position.set(0, 0, 0.01);
  group.add(textGroup);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    group.remove(plane);
    plane.geometry.dispose();
    material.dispose();
    group.remove(textGroup);
    // textGroup resources are managed by fontAtlas, no disposal needed
  };

  // Apply kinematic primitives (none specified)
  // (config.cinematicPrimitives is empty or undefined)

  // No event handlers needed

  return group;
}
